use crate::choice::{MultiChoice, SingleChoice};
use crate::error::SchematicError;
use serde::{Deserialize, Serialize};

/// Internal plumbing: generic container representing a slot in an unresolved schematic.
///
/// # Warning
/// This is an **internal plumbing** type used by code generated by `#[schematic]`.
/// Application code and end users should **never interact with `Slot` directly**.
/// If you are manually constructing or matching on `Slot` variants (`Choose`, `FixedUnresolved`, `FixedResolved`),
/// something is wrong in the API usage. Use macro-generated builders, [`SingleChoice`],
/// [`MultiChoice`], and the [`Schematic`](crate::Schematic) trait instead.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum Slot<U, R, C> {
    /// Slot contains a choice `C` waiting to be resolved.
    Choose(C),
    /// Slot contains a fixed, unresolved value `U`.
    FixedUnresolved(U),
    /// Slot contains a fixed, resolved value `R`.
    FixedResolved(R),
}

/// Internal plumbing: slot specialization for [`SingleChoice`].
///
/// # Warning
/// This is an **internal plumbing** type. Do not instantiate or match on `SingleSlot` directly.
/// Use the generated builders and pass raw values or [`SingleChoice`] instances directly.
pub type SingleSlot<U, R> = Slot<U, R, SingleChoice<U>>;

/// Internal plumbing: slot specialization for [`MultiChoice`].
///
/// # Warning
/// This is an **internal plumbing** type. Do not instantiate or match on `MultiSlot` directly.
/// Use the generated builders and pass collections or [`MultiChoice`] instances directly.
pub type MultiSlot<U, R> = Slot<U, R, MultiChoice<U>>;

impl<U, R, C> Slot<U, R, C> {
    pub fn as_choice(&self) -> Option<&C> {
        match self {
            Slot::Choose(c) => Some(c),
            _ => None,
        }
    }

    pub fn as_choice_mut(&mut self) -> Option<&mut C> {
        match self {
            Slot::Choose(c) => Some(c),
            _ => None,
        }
    }
}

impl<U, R> From<SingleChoice<U>> for SingleSlot<U, R> {
    fn from(choice: SingleChoice<U>) -> Self {
        Slot::Choose(choice)
    }
}

impl<U, R> From<MultiChoice<U>> for MultiSlot<U, R> {
    fn from(choice: MultiChoice<U>) -> Self {
        Slot::Choose(choice)
    }
}

impl<U, R> From<U> for SingleSlot<U, R> {
    fn from(value: U) -> Self {
        Slot::FixedUnresolved(value)
    }
}

impl<U, R> From<U> for MultiSlot<U, R> {
    fn from(value: U) -> Self {
        Slot::FixedUnresolved(value)
    }
}

impl<U, R> SingleSlot<U, R> {
    pub fn is_pending(&self) -> bool {
        match self {
            Slot::Choose(c) => !c.is_made(),
            _ => false,
        }
    }

    pub fn is_made(&self) -> bool {
        match self {
            Slot::Choose(c) => c.is_made(),
            _ => false,
        }
    }

    pub fn is_complete(&self) -> bool {
        match self {
            Slot::FixedUnresolved(_) | Slot::FixedResolved(_) => true,
            Slot::Choose(c) => c.is_made(),
        }
    }

    pub fn resolve_exact(self) -> Result<U, SchematicError> {
        match self {
            Slot::FixedUnresolved(u) => Ok(u),
            Slot::Choose(c) => c.resolve_exact(),
            Slot::FixedResolved(_) => Err(SchematicError::Custom("Slot already resolved".into())),
        }
    }
}

impl<U, R> MultiSlot<U, R> {
    pub fn is_pending(&self) -> bool {
        match self {
            Slot::Choose(c) => !c.is_made(),
            _ => false,
        }
    }

    pub fn is_made(&self) -> bool {
        match self {
            Slot::Choose(c) => c.is_made(),
            _ => false,
        }
    }

    pub fn is_complete(&self) -> bool {
        match self {
            Slot::FixedUnresolved(_) | Slot::FixedResolved(_) => true,
            Slot::Choose(c) => c.is_made(),
        }
    }

    pub fn resolve(self) -> Result<Vec<U>, SchematicError> {
        match self {
            Slot::FixedUnresolved(u) => Ok(vec![u]),
            Slot::Choose(c) => c.resolve(),
            Slot::FixedResolved(_) => Err(SchematicError::Custom("Slot already resolved".into())),
        }
    }
}
